// Package templates holds the standard spreadsheet templates for the admin
// imports (명단, 임무지역, 조별계획). The .xlsx files in this folder are the
// ones to hand out; they are generated by `make templates`
// (internal/templatebuild) and embedded so the setup screen can offer them
// for download.
package templates

import "embed"

//go:embed *.xlsx
var Files embed.FS

// ByKind maps the download key used in the API/UI to a file in Files.
var ByKind = map[string]string{
	"roster": "명단_서식.xlsx",
	"areas":  "임무지역_서식.xlsx",
	"plans":  "조별계획_서식.xlsx",
}
